<?php session_start();require 'conectare.php';$q=trim($_GET['cuvant']??'');$like='%'.$q.'%';$s=$pdo->prepare('SELECT DISTINCT c.id_carte,c.titlu,a.nume_autor,c.pret FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.titlu LIKE ? OR a.nume_autor LIKE ? OR c.descriere LIKE ? ORDER BY c.titlu');$s->execute([$like,$like,$like]);$books=$s->fetchAll();include 'page_top.php';include 'meniu.php';?><h1 class="page-title"><?=$q!==''?'Rezultate pentru „'.h($q).'”':'Catalog'?></h1><?php if(!$books):?><div class="empty">Nu am găsit rezultate.</div><?php else:?><div class="book-list"><?php foreach($books as $b):$id=(int)$b['id_carte'];$img="./coperti/$id.jpg"?><article class="book-row"><?php if(file_exists($img)):?><img src="<?=h($img)?>" alt=""><?php else:?><div class="mini-cover">Carte</div><?php endif;?><div><h3 class="book-title"><a href="carte.php?id_carte=<?=$id?>"><?=h($b['titlu'])?></a></h3><div class="author"><?=h($b['nume_autor'])?></div></div><div class="price"><?=number_format((float)$b['pret'],2,',','.')?> lei</div></article><?php endforeach;?></div><?php endif;include 'page_bottom.php';?>
